    'Open dashboard': 'افتح لوحة التحكم',
    'Action inbound leads, qualify customers with live call guidance, and hand over complete lead packs to sales.': 'تابِع العملاء المحتملين الواردين، وقيّم تأهيلهم بإرشادات مباشرة أثناء المكالمة، وسلّم ملفاتهم كاملةً إلى قسم المبيعات.',
    'Monitor all leads assigned to call center agents, call actioning, qualification quality, SLA risk and handover readiness.': 'مراقبة جميع العملاء المحتملين المسندين إلى موظفي مركز الاتصال، ومعالجة المكالمات، وجودة تقييم تأهيل العملاء، ومخاطر تجاوز مهلة الخدمة، ومدى الجاهزية للتسليم.',
    'Manage active leads, first contact, discovery, test drives, offers and customer follow-up.': 'أدِر العملاء قيد المتابعة، وعمليات التواصل الأول، وتحديد الاحتياجات، وتجارب القيادة، والعروض، والمتابعة.',
    'Greet arrivals, assign walk-ins and direct-to-showroom leads to executives, and keep first-contact SLA and floor flow on track.': 'استقبال الزوار، وإسناد العملاء الحاضرين دون موعد مسبق أو المتوجهين مباشرةً إلى صالة العرض إلى مسؤولي المبيعات، وضمان الالتزام بمهلة التواصل الأول وانسيابية سير العمل داخل صالة العرض.',
    'Monitor showroom flow, SLA breaches, exceptions, team workload, add-on penetration and blockers.': 'مراقبة سير العمل في صالة العرض، وحالات تجاوز مهلة الخدمة، والاستثناءات، وعبء عمل الفريق، ونسبة بيع الإضافات، والعوائق التي تعرقل سير العمل.',
    'Oversee network sales performance, target attainment, pipeline health, showroom rankings and executive escalations.': 'أشرف على أداء المبيعات في شبكة المعارض، وراقب تحقيق الأهداف، وتأكد من سلامة مسار المبيعات، واطلع على ترتيب صالات العرض، وتعامل مع المسائل التي تتطلب التصعيد إلى الإدارة العليا.',
