    'Accept — pick up the open enquiry and confirm next step.': 'اقبل — تولَّ الاستفسار القائم وأكّد الخطوة التالية.',
    '· SLA logic pending final alignment (Chaitanya / George).': '· آلية احتساب اتفاقية مستوى الخدمة بانتظار الاتفاق النهائي (تشايتانيا / جورج).',
    'Bar height = stage volume · % = stage-to-stage conversion': 'ارتفاع العمود = حجم المرحلة  ·  النسبة المئوية % = معدل التحويل بين المراحل',
