    'Agent Scores Review': 'مراجعة تقييمات أداء الموظفين',
    'Average score and the scored calls behind it. Coaching is flagged under 70.': 'متوسط التقييم والمكالمات التي استُخدمت في احتسابه. تُحدَّد الحاجة إلى التدريب عند انخفاض المتوسط عن 70.',
