    'Communication': 'التواصل',
    'Clear enough, with a couple of hesitant phrases near the close.': 'كان التواصل واضحًا بدرجة مقبولة، مع بعض عبارات التردد قرب نهاية المكالمة.',
    'Model and budget were answered. Timeline stayed vague.': 'تم الحصول على إجابات بشأن الطراز والميزانية، لكن الإطار الزمني المتوقع ظل غير واضح.',
    'Objection handling': 'التعامل مع اعتراضات العميل',
    'The price objection was heard, then answered only in general terms.': 'استمع الموظف إلى اعتراض العميل بشأن السعر، لكنه رد عليه بعبارات عامة فقط.',
    'Response time': 'سرعة الاستجابة',
    'Replies were steady, inside the scoring range.': 'كانت الردود منتظمة وضمن النطاق الزمني المعتمد للتقييم.',
    'Mark Reviewed': 'تحديد كمُراجَع',
    'A weekend test drive was proposed and left open.': 'تم اقتراح تجربة قيادة خلال عطلة نهاية الأسبوع، دون تأكيد الموعد.',
    'Polite and easy to follow.': 'كان التواصل مهذبًا وواضحًا وسهل الفهم.',
    'Budget, usage and model were answered.': 'تم الحصول على إجابات بشأن الميزانية والاستخدام والطراز.',
    'A feature question was answered, with one spec left vague.': 'تمت الإجابة عن استفسار بشأن إحدى ميزات السيارة، لكن بقيت إحدى المواصفات غير واضحة.',
    'Median reply time sat inside the scoring range.': 'كان الوسيط الزمني للردود ضمن النطاق المعتمد للتقييم.',
    'Agreed to visit, but the slot and preferred contact time were not pinned down.': 'وافق العميل على الزيارة، لكن لم يتم تحديد موعد الزيارة أو الوقت المفضّل للتواصل معه.',
    'Polite and clear in the customer’s language.': 'كان التواصل مهذبًا وواضحًا بلغة العميل.',
    'The customer agreed to visit, but the slot was not pinned down.': 'وافق العميل على الزيارة، لكن لم يتم تحديد موعدها.',
    'Usage and budget were captured. Preferred contact time was not.': 'تم تسجيل معلومات الاستخدام والميزانية، لكن لم يتم تحديد الوقت المفضّل للتواصل مع العميل.',
    'The customer raised no objection about the car.': 'لم يُبدِ العميل أي اعتراض بشأن السيارة.',
    'The visit was already booked. A competitor comparison was not answered from the vehicle facts.': 'كان موعد الزيارة محجوزًا مسبقًا، ولم تتم الإجابة عن المقارنة مع سيارة منافسة بالاستناد إلى المعلومات الفعلية عن السيارة.',
    'Understandable, and the language matched the customer.': 'كان التواصل مفهومًا وباللغة المناسبة للعميل.',
    'The customer already had a visit booked, and this call did not move it forward.': 'كان لدى العميل موعد زيارة محجوز مسبقًا، ولم تُسهم هذه المكالمة في إحراز أي تقدم بشأنه.',
    'The visit was already booked before this call, so discovery does not apply.': 'كان موعد الزيارة محجوزًا قبل هذه المكالمة، لذا لا ينطبق معيار استكشاف احتياجات العميل في هذه الحالة.',
    'A competitor comparison was acknowledged but not answered from the vehicle facts.': 'أبدى الموظف تفهّمًا للمقارنة مع سيارة منافسة، لكنه لم يُجب عنها بالاستناد إلى المعلومات الفعلية عن السيارة.',
    'Replies were prompt.': 'كانت الردود سريعة.',
