    'L2 ADAS and the 540° camera on every trim, not just the top one': 'أنظمة مساعدة السائق المتقدمة من المستوى الثاني (L2 ADAS) وكاميرا بزاوية رؤية 540 درجة متوفرة في جميع الفئات، وليس في الفئة الأعلى فقط.',
