    'Undercuts the Japanese mid-size set by roughly AED 10–20k': 'سعرها أقل بنحو 10,000 إلى 20,000 درهم إماراتي مقارنةً بمنافسيها اليابانيين من فئة السيارات متوسطة الحجم.',
