    '2.0T 261 hp, quilted leather and twin 12.3-inch screens as standard': 'محرك 2.0T بقوة 261 حصانًا، ومقاعد جلدية مبطنة بتصميم ماسي، وشاشتان مزدوجتان بقياس 12.3 بوصة كتجهيزات قياسية.',
