    'Mid-size space at compact money — 500 L boot': 'سيارات متوسطة الحجم بمساحة رحبة وسعر معقول، مع سعة 500 لتر لصندوق الأمتعة.',
    '1.6T 197 hp at 7.8 L/100km, the cheapest in the line-up to run': 'محرك 1.6T بقوة 197 حصانًا واستهلاك وقود يبلغ 7.8 لتر لكل 100 كم، وهو الأقل تكلفة في التشغيل ضمن تشكيلة الطرازات.',
    'L2 ADAS standard plus the 5-year service pack': 'أنظمة مساعدة السائق المتقدمة من المستوى الثاني (L2 ADAS) كتجهيز قياسي، بالإضافة إلى باقة صيانة لمدة 5 سنوات.',
