    'I confirm that I have received the above vehicle in good condition for test drive purposes, that I am the owner of the above licence and legally allowed to drive the demonstration vehicle. I will not drive off-road unless authorised, and I agree to reimburse any expenses from damage due to my negligence. In case of an accident that is my fault, I agree to pay the insurance excess.': 'أُقر باستلام هذه المركبة بحالة جيدة لتجربة القيادة، وبأنني صاحب الرخصة الموضحة في هذا النموذج ويحق لي قانونًا قيادة سيارة العرض. لن أقود على الطرق الوعرة دون إذن، وأوافق على تعويض أي تكاليف عن أضرار ناتجة عن إهمالي. وفي حال وقوع حادث بسبب خطئي، أوافق على دفع مبلغ التحمّل في التأمين.',
