    [/^(ث|ثانية|ثوانٍ|ثوان)$/, ['ثانية واحدة', 'ثانيتان', 'ثانيتين', 'ثوانٍ', 'ثانية']],
    [/^(ي|يوم|أيام|يومًا|يومان|يومين)$/, ['يوم واحد', 'يومان', 'يومين', 'أيام', 'يومًا']],
    [/^(أسبوع|أسابيع|أسبوعًا)$/, ['أسبوع واحد', 'أسبوعان', 'أسبوعين', 'أسابيع', 'أسبوعًا']],
    [/^(شهر|أشهر|شهرًا)$/, ['شهر واحد', 'شهران', 'شهرين', 'أشهر', 'شهرًا']],
    [/^(مرة|مرات)$/, ['مرة واحدة', 'مرتان', 'مرتين', 'مرات', 'مرة']],
    [/^(نقطة|نقاط)$/, ['نقطة واحدة', 'نقطتان', 'نقطتين', 'نقاط', 'نقطة']]
